850	    const [project, directGoal] = await Promise.all([projectPromise, directGoalPromise]);
851	
852	    if (directGoal) {
853	      return { project, goal: directGoal };
854	    }
855	
856	    const projectGoalId = project?.goalId ?? project?.goalIds[0] ?? null;
857	    if (projectGoalId) {
858	      const projectGoal = await goalsSvc.getById(projectGoalId);
859	      return { project, goal: projectGoal };
860	    }
861	
862	    if (!issue.projectId) {
863	      const defaultGoal = await goalsSvc.getDefaultCompanyGoal(issue.companyId);
864	      return { project, goal: defaultGoal };
865	    }
866	
867	    return { project, goal: null };
